"""Render retained catalog records without requiring historical acquisition inputs."""
import html
import json
from pathlib import Path

H = Path(__file__).resolve().parents[1]

def render(rows, regs, counts):
    def esc(s):return html.escape(str(s or ''))
    def link(url,label):return '<a href="'+esc(url)+'">'+esc(label)+'</a>'if url else esc(label)
    def files(fs):
     fs=[dict(local_file=f)if isinstance(f,str)else f for f in fs]
     return '<br>'.join(link(('previews/'+Path(f['local_file']).name) if (H/'previews'/Path(f['local_file']).name).is_file() else 'assets/'+f['local_file'],Path(f['local_file']).name)+(' · '+link(f.get('url'), 'source')if f.get('url')else '')for f in fs if f.get('local_file'))
    def page(title,body,headers,trs):
     return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'''+esc(title)+'''</title><style>body{font:15px system-ui;margin:24px;color:#203040}a{color:#1260a0}table{border-collapse:collapse;width:100%}td,th{padding:10px;border:1px solid #cbd5df;text-align:left;vertical-align:top}th{background:#e8eef3;position:sticky;top:0}td{min-width:150px;max-width:420px;overflow-wrap:anywhere}img{width:230px;max-height:260px;object-fit:contain}input,select{padding:10px;margin:12px 8px 12px 0}small{color:#52616f}.candidate{background:#fff9e9}</style><h1>'''+esc(title)+'''</h1>'''+body+'''<p><a href="structure_map.html">Structure map</a> · <a href="publication_registry.html">Publication search registry</a> · <a href="catalog.html">Image-scored subset</a> · <a href="SEARCH_COVERAGE.md">Coverage and gaps</a> · <a href="acs_expansion_summary.json">ACS acquisition report</a> · <a href="acs_access_resolution.json">Access recovery</a> · <a href="acs_source_index.json">Source-page index</a> · <a href="acs_native_file_inventory.json">New original-file inventory</a></p><input id="q" aria-label="Search" placeholder="Search all columns"><select id="status" aria-label="Review status"><option value="">All statuses</option><option value="reviewed_in_scope">Reviewed in scope</option><option value="candidate">Candidates</option></select><span id="count"></span><table><thead><tr>'''+''.join('<th>'+esc(h)+'</th>'for h in headers)+'''</tr></thead><tbody>'''+''.join(trs)+'''</tbody></table><script>const q=document.querySelector('#q'),s=document.querySelector('#status'),rows=[...document.querySelectorAll('tbody tr')];function filter(){let n=0;for(const r of rows){const ok=r.textContent.toLowerCase().includes(q.value.toLowerCase())&&(!s.value||r.dataset.status===s.value);r.hidden=!ok;if(ok)n++}document.querySelector('#count').textContent=n+' rows shown'}q.oninput=filter;s.onchange=filter;filter()</script></html>'''
    trs=[]
    for r in rows:
     st=r['staple_list'];ch=r['structural_characterization'];im=r['imaging_datasets'];image=link('assets/'+r['image_file'],'<image>')if r.get('image_file')else 'Image not scored; see source links'
     if r.get('image_file'):image='<a href="assets/'+esc(r['image_file'])+'"><img loading="lazy" alt="Published design image '+esc(r['id'])+'" src="assets/'+esc(r['image_file'])+'"></a><br>Image-only score: '+str(r['quality_score'])+'<br>'+link(r.get('image_source_url'),'image source')
     resources=im.get('resources',[])
     cells=[esc(r['id'])+'<br>'+esc(r['map_status']),link(r['publication_url'],r['publication'])+'<br>'+esc(r['doi'])+'<br>'+esc(r['first_publication_date']),esc(r['design'])+'<br><small>Family: '+esc(r['family'])+'</small>',esc(r['lattice'])+'<br>'+esc(r.get('lattice_evidence','')),image,esc(st['status'])+'<br>'+esc(st.get('location'))+'<br>'+esc(st.get('notes'))+'<details><summary>Sources and downloaded supplements</summary>'+files(st.get('sources',[]))+files(r.get('publication_supplements',[]))+'</details>',esc('; '.join(ch.get('modalities',[])))+'<br>'+esc(ch.get('simulation_comparison_notes',''))+'<br>'+link(ch.get('source_url'),'characterization source'),esc(im.get('public_raw_dataset_status'))+'<br>'+'<br>'.join(link(f.get('url'),f.get('accession')or f.get('label')or f.get('kind'))+' '+esc(f.get('kind'))for f in resources),files(r.get('design_files',[]))or 'No matching original verified',esc(r.get('notes',r.get('quality_rationale',''))) ]
     trs.append('<tr class="'+r['map_status']+'" data-status="'+r['map_status']+'">'+''.join('<td>'+c+'</td>'for c in cells)+'</tr>')
    body=f'<p><strong>Research side project — literature evidence and design review; no molecular reconstruction performed by this workflow.</strong></p><p>{counts["reviewed_design_groups"]} reviewed design groups across {counts["reviewed_publications"]} publications; {counts["candidate_design_groups"]} candidate groups. These are grouped variants, not unique-architecture counts. Staple-list availability does not certify completeness. Missing image scores remain unassigned.</p><p><a href="structure_map.csv">CSV</a> · <a href="structure_map.json">JSON</a> · <a href="imaging_resources.csv">Imaging resources</a> · <a href="expansion_repository_files.csv">Additional original files</a> · <a href="priority_review_gaps.csv">Priority review gaps</a></p>'
    (H/'structure_map.html').write_text(page('Pre-2020 DNA origami structure map',body,['ID / status','Publication','Design / family','Lattice','Image / score','Staple lists','Characterization','Imaging data','Original files','Qualifications'],trs))
    trs=[]
    for r in regs:
     cells=[esc(r['id'])+'<br>'+esc(r['review_status']),link(r['publication_url'],r['publication'])+'<br>'+esc(r['doi'])+'<br>'+esc(r['first_publication_date']),esc(', '.join(r['structure_ids'])),esc(r['fulltext_status'])+'<br>'+esc('; '.join(r['discovery'])),esc(r['priority'])+'<details><summary>Primary-text evidence snippets (unverified matches)</summary>'+esc(json.dumps(r.get('sequence_evidence',[]),ensure_ascii=False))+'</details>',files(r['downloaded_supplements']),esc('; '.join(r.get('repository_links',[])))]
     trs.append('<tr data-status="'+('reviewed_in_scope'if r['review_status']=='contains_reviewed_structure_groups'else 'candidate')+'">'+''.join('<td>'+c+'</td>'for c in cells)+'</tr>')
    (H/'publication_registry.html').write_text(page('Pre-2020 publication search registry',f'<p>{len(regs)} discovery records. This includes reviews, methods, preprints, out-of-scope papers and unresolved sources. It is not a count of eligible publications. Search snippets are automated evidence leads.</p><p><a href="publication_registry.csv">CSV</a> · <a href="publication_registry.json">JSON</a></p>',['Status','Publication','Structure IDs','Coverage','Evidence leads','Downloaded sources','Named repositories'],trs))
